// String API corners: indexOf with ranges, substring variants, replace, case, compare, regionMatches, split limits, chars
fun main() {
    val s = "Hello, World"
    println(s.indexOf('o')); println(s.indexOf('o', 5)); println(s.lastIndexOf('o')); println(s.indexOf("World")); println(s.indexOf("x")); println(s.indexOf("")); println(s.lastIndexOf("")); println(s.indexOf("o", -5)); println(s.indexOf("o", 100)); println(s.indexOfAny(listOf("W", "e")))
    println(s.substring(7)); println(s.substring(0, 5)); println(s.substringBefore(",")); println(s.substringAfter(", ")); println(s.substringBefore("z", "none")); println(s.substringAfterLast("o")); println(s.take(3) + s.takeLast(3)); println(s.drop(10)); println(s.removeRange(5, 7)); println(s.removePrefix("Hello")); println(s.removeSuffix("World"))
    println(s.replace("o", "0")); println(s.replace('l', 'L')); println(s.replaceFirst("l", "_")); println(s.replace("", "-").length); println(s.replace(Regex("[aeiou]")) { it.value.uppercase() }); println("aaa".replace("aa", "b")); println(s.replaceRange(0, 5, "Bye")); println("a.b.c".replace(".", "")); println("abc".replace("", "|"))
    println(s.uppercase()); println(s.lowercase()); println("hello world".split(" ").joinToString(" ") { it.replaceFirstChar { c -> c.uppercase() } }); println("straße".uppercase())
    println("abc".compareTo("abd")); println("abc".compareTo("ab")); println("a".compareTo("B")); println("a".compareTo("B", ignoreCase = true)); println("abc".equals("ABC", true)); println("abc".startsWith("AB", true)); println("abc".endsWith("bc")); println("abc".contains("B", true)); println("hello".regionMatches(1, "ell", 0, 3)); println("abc" == "abc"); println("a" < "b")
    println("a,b,,c".split(",")); println("a,b,,c".split(",", limit = 2)); println("a,b,,c".split(",").filter { it.isNotEmpty() }); println("  a  b ".split(" ")); println("abc".split("b")); println("abc".split("c")); println("".split(",")); println("a1b22c".split(Regex("\\d+"))); println("one two".split(' ', limit = 5))
    println("abc".reversed()); println("abc".toList()); println("abc".toCharArray().size); println("abc".asSequence().map { it.code }.toList()); println("hello".count { it == 'l' }); println("hello".groupBy { it }.mapValues { it.value.size }); println("hello".toSet().size); println("b a c".split(" ").sorted()); println("hello".all { it.isLetter() }); println("hello".first()); println("hello".last()); println("hello".single { it == 'h' })
    println("abc".isEmpty()); println("".isEmpty()); println("  ".isBlank()); println("abc".isNotBlank()); println("abc".length); println("abc".getOrNull(5)); println("abc".getOrElse(5) { '?' }); println("abc".elementAt(1)); println("abc".lastIndex); println("abc".indices); println("a-b".trim('a')); println("xxhixx".trimStart('x')); println("xxhixx".trimEnd('x')); println(" \t\n a \n".trim())
    println("abc".padStart(2)); println("abc".padEnd(5, '*')); println("5".padStart(3, '0')); println("abc".repeat(0).length); println("ab".repeat(3)); println("a".plus("b")); println("abc".commonPrefixWith("abd")); println("abc".commonSuffixWith("xbc")); println("a b".capitalize2()); println("%d items".format(3)); println("%05.1f|%-5s|%5s|%x".format(3.14159, "ab", "cd", 255)); println("%c%c".format('a', 66)); println("%,d".format(1234567)); println("%+d".format(5)); println("%b %s".format(true, null))
    println("abc".chunked(2)); println("abcdef".windowed(3, 2)); println("abc".zip("xyz")); println("abc".zipWithNext()); println("a-b-c".split("-").reversed().joinToString("+")); println("abc".mapIndexed { i, c -> c + i }.joinToString("")); println("hello world".filter { it !in "aeiou" }); println("ab".flatMap { listOf(it, it) }); println("abc".fold(0) { a, c -> a * 31 + c.code }); println("hello"[1]); println("abc".firstOrNull { it > 'a' }); println("4 5".split(" ").map(String::toInt).sum())
}
fun String.capitalize2() = replaceFirstChar { it.uppercase() }
